CREATE VIEW HEAD_LST_FBK AS SELECT        TOP (100) PERCENT NUMBER, TAG AS htag, TAG - 2 AS dtag, ANBAR, NUMBER1, DATE_N, TAH, MAS, VAS, N_S, CUST_NO, MOLAH, M_NAGHD, MABL_VAR,                         MOIN_VAR, MABL_HAV, MOIN_HAV, MABL_HAZ, MOIN_HAZ, TAKHFIF, MOIN_KHF, ANBARF, FNUMCO, USER_NAME, DEPATMAN, SHIFT, CUST_KIND, MBAA,                         HMBAA, OKF, CDDATE, CDTIME, OKDATE, OKTIME, SHARAYET, SGN1, SGN2, SGN3, SGN4, TAMIR, TICMBAA, TKHF, SADER, ARZD, ARZKIND, JAY,                         MODAT_PPID , PEPID, PEID, SGN1usid, sgn2usid, sgn3usid,UID FROM dbo.HEAD_LST WHERE (TAG = 4) ORDER BY NUMBER
